import java.util.ArrayDeque;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class StockExchangeDemo {

    public enum Side { BUY, SELL }

    public static class Order {
        final String id;
        final String traderId;
        final Side side;
        final long priceCents;
        int remainingQty;

        public Order(String id, String traderId, Side side, long priceCents, int qty) {
            this.id = id;
            this.traderId = traderId;
            this.side = side;
            this.priceCents = priceCents;
            this.remainingQty = qty;
        }

        @Override
        public String toString() {
            return side + " " + remainingQty + "@$" + (priceCents / 100.0) + " (" + traderId + ")";
        }
    }

    public static class LimitOrderBook {
        final TreeMap<Long, ArrayDeque<Order>> bids = new TreeMap<>(Collections.reverseOrder());
        final TreeMap<Long, ArrayDeque<Order>> asks = new TreeMap<>();
        final Map<String, Long> traderCash = new HashMap<>();
        final Map<String, Integer> traderStock = new HashMap<>();

        public void initTrader(String trader, long cash, int shares) {
            traderCash.put(trader, cash);
            traderStock.put(trader, shares);
        }

        public void placeOrder(Order order) {
            if (order.side == Side.BUY) {
                matchBuy(order);
            } else {
                matchSell(order);
            }
        }

        private void matchBuy(Order buy) {
            while (buy.remainingQty > 0 && !asks.isEmpty()) {
                long bestAskPrice = asks.firstKey();
                if (buy.priceCents < bestAskPrice) break; // Spread open

                ArrayDeque<Order> queue = asks.get(bestAskPrice);
                Order restingAsk = queue.peek();

                int fillQty = Math.min(buy.remainingQty, restingAsk.remainingQty);
                settle(buy.traderId, restingAsk.traderId, bestAskPrice, fillQty);

                buy.remainingQty -= fillQty;
                restingAsk.remainingQty -= fillQty;

                if (restingAsk.remainingQty == 0) {
                    queue.poll();
                }
                if (queue.isEmpty()) {
                    asks.remove(bestAskPrice);
                }
            }
            if (buy.remainingQty > 0) {
                bids.computeIfAbsent(buy.priceCents, k -> new ArrayDeque<>()).add(buy);
            }
        }

        private void matchSell(Order sell) {
            while (sell.remainingQty > 0 && !bids.isEmpty()) {
                long bestBidPrice = bids.firstKey();
                if (sell.priceCents > bestBidPrice) break; // Spread open

                ArrayDeque<Order> queue = bids.get(bestBidPrice);
                Order restingBid = queue.peek();

                int fillQty = Math.min(sell.remainingQty, restingBid.remainingQty);
                settle(restingBid.traderId, sell.traderId, bestBidPrice, fillQty);

                sell.remainingQty -= fillQty;
                restingBid.remainingQty -= fillQty;

                if (restingBid.remainingQty == 0) {
                    queue.poll();
                }
                if (queue.isEmpty()) {
                    bids.remove(bestBidPrice);
                }
            }
            if (sell.remainingQty > 0) {
                asks.computeIfAbsent(sell.priceCents, k -> new ArrayDeque<>()).add(sell);
            }
        }

        private void settle(String buyer, String seller, long price, int qty) {
            long cost = price * qty;
            traderCash.put(buyer, traderCash.get(buyer) - cost);
            traderCash.put(seller, traderCash.get(seller) + cost);
            traderStock.put(buyer, traderStock.get(buyer) + qty);
            traderStock.put(seller, traderStock.get(seller) - qty);
            System.out.printf("  [TRADE] %d shares @ $%.2f | Buyer: %s | Seller: %s\n",
                qty, price / 100.0, buyer, seller);
        }
    }

    public static void main(String[] args) {
        LimitOrderBook book = new LimitOrderBook();
        book.initTrader("Alice", 1000000, 100); // $10,000, 100 shares
        book.initTrader("Bob", 1000000, 100);

        // Alice places resting Ask: SELL 50 @ $150.00
        book.placeOrder(new Order("O1", "Alice", Side.SELL, 15000, 50));
        System.out.println("Resting Asks: " + book.asks);

        // Bob places crossing Bid: BUY 30 @ $150.00 (Partial Fill of 30 shares)
        book.placeOrder(new Order("O2", "Bob", Side.BUY, 15000, 30));
        System.out.println("Asks after partial fill: " + book.asks);
        System.out.println("Bob Cash: $" + (book.traderCash.get("Bob") / 100.0) + " | Shares: " + book.traderStock.get("Bob"));
    }
}
