import java.util.ArrayDeque;
import java.util.Map;

public class QueueInserter {
    public static void enqueueOrder(Map<Long, ArrayDeque<String>> book, long price, String orderId) {
        if (book != null && orderId != null) {
            book.computeIfAbsent(price, k -> new ArrayDeque<>()).addLast(orderId);
        }
    }
}

