import java.util.Map;

public class CashSettler {
    public static void settleCash(Map<String, Long> balances, String buyer, String seller, long totalCostCents) {
        if (balances == null || buyer == null || seller == null) return;
        balances.put(buyer, balances.getOrDefault(buyer, 0L) - totalCostCents);
        balances.put(seller, balances.getOrDefault(seller, 0L) + totalCostCents);
    }
}
